import{_ as r,o as e,c as o,ag as n}from"./chunks/framework.C5oN-8Wt.js";const p=JSON.parse('{"title":"从录制的 GPS 信号算出位置","description":"","frontmatter":{},"headers":[],"relativePath":"v0.5.0-beta/learn/recorded-gnss/index.md","filePath":"v0.5.0-beta/learn/recorded-gnss/index.md"}'),s={name:"v0.5.0-beta/learn/recorded-gnss/index.md"};function a(d,t,g,l,i,h){return e(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="从录制的-gps-信号算出位置" tabindex="-1">从录制的 GPS 信号算出位置 <a class="header-anchor" href="#从录制的-gps-信号算出位置" aria-label="Permalink to &quot;从录制的 GPS 信号算出位置&quot;">​</a></h1><p>地面站地图上的无人机位置，从哪里来？机载导航接收机接收卫星信号并算出经纬度，再由飞控把定位结果送给地面站。本课从接收机这一环开始，用保存下来的 GPS 信号算一次位置。</p><h2 id="运行示例" tabindex="-1">运行示例 <a class="header-anchor" href="#运行示例" aria-label="Permalink to &quot;运行示例&quot;">​</a></h2><ol><li>确认<a href="./../../setup/linux-environment/">导航实验环境</a>显示 <strong>环境已就绪</strong>。</li><li>点击 Master 左侧的 <strong>导航</strong>，打开 <strong>录制信号定位</strong>。画布上有两个模块，<strong>GNSS 录制信号源</strong>的“录制文件”输出接到 <strong>GNSS 接收机</strong>的“录制文件”输入。信号源的“原始 IQ 样本”保留为 <strong>内置定位样本</strong>。</li><li>按 <strong>F5</strong> 运行。第一组坐标需要等接收机找到足够的卫星、读出卫星发来的信息之后才会出现。样本读完，实验自动结束，本次结果可以继续查看。</li></ol><p>GNSS-SDR 读取样本时会先从录制的数据里搜索卫星信号，再跟踪每颗卫星信号的变化，读出导航电文并估计信号传播的时间。接收机把多颗卫星的观测组合起来，求出自己的位置。录制文件里的 I、Q 是同一时刻的一对信号数值，也就是接收机拿到的原始输入。这段样本记录了约 100 秒的卫星信号。<a href="https://gnss-sdr.org/my-first-fix/" target="_blank" rel="noreferrer">GNSS-SDR 首次定位样本</a></p><h2 id="用观察器读坐标和点分布" tabindex="-1">用观察器读坐标和点分布 <a class="header-anchor" href="#用观察器读坐标和点分布" aria-label="Permalink to &quot;用观察器读坐标和点分布&quot;">​</a></h2><p>通过 <strong>编辑 → 插入 → 观察器</strong> 添加工具。打开观察器的 <strong>参数</strong>页，在捕获变量输入框中输入下表里的变量名，从下拉结果中选择来自当前工程的 <strong>GNSS 接收机</strong>输出。点击 <strong>添加捕获变量</strong> 可增加输入。</p><table tabindex="0"><thead><tr><th>想看什么</th><th>绑定变量</th><th>怎样读图</th></tr></thead><tbody><tr><td>接收机在哪里</td><td>绑定“纬度”“经度”，也可添加“高程”。</td><td>切到 <strong>输出</strong>页查看坐标，纬度和经度用度，高程用米。</td></tr><tr><td>每次算出的点怎样分布</td><td>用另一台观察器，先绑定“东向偏移”，再绑定“北向偏移”。在 <strong>输出</strong>页选择 <strong>XY 关系图</strong>。</td><td>横轴向东，纵轴向北，单位都是米。原点对应本轮算出的第一个定位点，图上的每个点对应一次定位结果。</td></tr></tbody></table><p>先记录一组经纬度，再看散点是集中在一小片区域，还是在某个方向上铺得更宽。把点分布与两个轴的刻度结合起来，就能估计这段样本的定位结果在水平方向散开了多远。</p><h2 id="另存为自己的工程-改一个参数再试" tabindex="-1">另存为自己的工程，改一个参数再试 <a class="header-anchor" href="#另存为自己的工程-改一个参数再试" aria-label="Permalink to &quot;另存为自己的工程，改一个参数再试&quot;">​</a></h2><ol><li>用 <strong>文件 → 另存为…</strong> 保存一份自己的工程。</li><li>点击画布上的 <strong>GNSS 接收机</strong>，保持样本和其他参数不变，只把 <strong>多普勒搜索上限</strong>从 <strong>10,000 Hz</strong> 改为 <strong>9,500 Hz</strong>。</li><li>按 <strong>F5</strong> 再运行一次，比较两轮能否得到定位结果、散点的分布有没有明显变化。</li></ol><p>卫星与接收机的相对运动会使接收到的频率产生偏移。调低搜索上限后，接收机检查的频偏范围缩小。信号的频偏超出搜索范围时，接收机就可能找不到这颗卫星。对照时把每轮的参数、是否求得位置和点分布一起记录下来。</p><p><a href="./../../modules/gnss_recording_source/">GNSS 录制信号源</a> · <a href="./../../modules/gnss_receiver/">GNSS 接收机</a></p>',13)])])}const S=r(s,[["render",a]]);export{p as __pageData,S as default};
